+export function jsonToolSchema(input: {
+  required?: string[];
+  properties: JsonObject;
+}): JsonObject {
+  return {
+    type: 'object',
+    properties: input.properties,
+    additionalProperties: false,
+    ...(input.required && input.required.length > 0 ? { required: input.required } : {}),
+  };
+}
